class FakeEffect {
    private var lastKey: Any? = null
    var launches = 0
    fun run(key: Any?) {
        if (key != lastKey) { lastKey = key; launches++ }
    }
}

fun main() {
    val stable = FakeEffect()
    val unstable = FakeEffect()
    repeat(4) {
        stable.run("user-42")
        unstable.run(Any())
    }
    println("${stable.launches} ${unstable.launches}")
}

