class Holder<T>(var value: T)

fun main() {
    var onTimeout: () -> String = { "old" }
    val captured = onTimeout
    val latest = Holder(onTimeout)

    onTimeout = { "new" }      // parent passes a new lambda
    latest.value = onTimeout   // holder is updated

    println(captured() + " " + latest.value())
}

val lifecycleOwner = LocalLifecycleOwner.current
DisposableEffect(lifecycleOwner) {
    val observer = LifecycleEventObserver { _, event ->
        if (event == Lifecycle.Event.ON_START) onStart()
        if (event == Lifecycle.Event.ON_STOP) onStop()
    }
    lifecycleOwner.lifecycle.addObserver(observer)
    onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
}
